using System.Diagnostics;
using System.Runtime.CompilerServices;
using Microsoft.Extensions.Caching.Memory;

namespace DevLab.Api.Features.AsyncConcurrency;

public record IoCall(string Name, int DelayMs, int ThreadBefore, int ThreadAfter);
public record WhenAllResult(long SequentialMs, long ParallelMs, IReadOnlyList<IoCall> Calls);
public record WhenAnyResult(string Winner, long ElapsedMs, int ServiceMs, int TimeoutMs);
public record StreamItem(int Index, DateTimeOffset ProducedAt, int Thread);
public record SlowRun(string RunId, string Status, int StepReached, int Steps, DateTimeOffset At);
public record ValueTaskResult(string Key, decimal Value, bool CompletedSynchronously, double Ms, long TaskBytes, long ValueTaskBytes, int Iterations);

/// <summary>
/// Async &amp; concurrency lesson. Every endpoint MEASURES something: durations, thread ids,
/// in-flight counts, allocations. All inputs are clamped: this runs on a shared instance.
/// </summary>
public static class AsyncConcurrencyLesson
{
    public static IServiceCollection AddAsyncConcurrencyLesson(this IServiceCollection services)
    {
        services.AddMemoryCache();
        services.AddSingleton<SlowRunLog>();
        services.AddSingleton<PriceCache>();
        services.AddSingleton<ThreadPoolDemo>();
        return services;
    }

    public static IEndpointRouteBuilder MapAsyncConcurrencyEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/async").WithTags("Async");

        group.MapGet("/whenall", WhenAllAsync);
        group.MapGet("/whenany", WhenAnyAsync);

        // IAsyncEnumerable<T>: System.Text.Json writes the JSON array element by element
        // and flushes while the next element is pending → the client sees items arrive.
        group.MapGet("/stream", (int? count, int? delayMs, CancellationToken ct) =>
            ProduceAsync(Math.Clamp(count ?? 8, 1, 20), Math.Clamp(delayMs ?? 400, 10, 1000), ct));

        group.MapGet("/slow", SlowAsync);
        group.MapGet("/slow/log", (SlowRunLog log) => TypedResults.Ok(log.Recent()));
        group.MapGet("/valuetask", ValueTaskAsync);

        ConcurrencyDemos.Map(group);
        ThreadPoolDemo.Map(group);
        return app;
    }

    private const int Iterations = 100_000;

    // 1. Sequential awaits (≈ sum of delays) vs Task.WhenAll (≈ max of delays).
    private static async Task<IResult> WhenAllAsync(CancellationToken ct)
    {
        (string Name, int DelayMs)[] calls = [("users", 300), ("orders", 450), ("stock", 200), ("prices", 350), ("reviews", 250)];

        var sw = Stopwatch.StartNew();
        foreach (var (name, delay) in calls)
            await SimulatedIoAsync(name, delay, ct);       // each await waits for the previous one
        var sequentialMs = sw.ElapsedMilliseconds;

        sw.Restart();
        var tasks = calls.Select(c => SimulatedIoAsync(c.Name, c.DelayMs, ct)).ToArray(); // all started NOW
        var results = await Task.WhenAll(tasks);                                           // then awaited together
        var parallelMs = sw.ElapsedMilliseconds;

        return TypedResults.Ok(new WhenAllResult(sequentialMs, parallelMs, results));
    }

    // 2. Task.WhenAny: first one wins — here a timeout racing a slow service.
    private static async Task<IResult> WhenAnyAsync(int? serviceMs, int? timeoutMs, CancellationToken ct)
    {
        var service = Math.Clamp(serviceMs ?? 800, 10, 2000);
        var timeout = Math.Clamp(timeoutMs ?? 500, 10, 2000);
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);

        var sw = Stopwatch.StartNew();
        var serviceTask = Task.Delay(service, cts.Token);
        var timeoutTask = Task.Delay(timeout, cts.Token);
        var first = await Task.WhenAny(serviceTask, timeoutTask);
        await cts.CancelAsync();   // the loser keeps running unless YOU cancel it

        // Shortcut since .NET 6: await serviceTask.WaitAsync(TimeSpan.FromMilliseconds(timeout), ct)
        return TypedResults.Ok(new WhenAnyResult(first == serviceTask ? "service" : "timeout", sw.ElapsedMilliseconds, service, timeout));
    }

    // 3. CancellationToken: bound to HttpContext.RequestAborted. Client aborts → token fires →
    //    Task.Delay throws OperationCanceledException → we stop working for nobody.
    private static async Task<IResult> SlowAsync(string runId, int? steps, int? stepMs, SlowRunLog log, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(runId) || runId.Length > 64)
            return TypedResults.BadRequest(new { error = "runId is required (≤ 64 chars)." });

        var total = Math.Clamp(steps ?? 10, 1, 10);
        var delay = Math.Clamp(stepMs ?? 500, 10, 1000);
        var step = 0;
        try
        {
            for (step = 1; step <= total; step++)
                await Task.Delay(delay, ct);    // a real handler passes ct to EF Core / HttpClient the same way
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            log.Add(new SlowRun(runId, "cancelled", step, total, DateTimeOffset.UtcNow));
            return TypedResults.Empty;          // the client is gone: nothing to send
        }

        var run = new SlowRun(runId, "completed", total, total, DateTimeOffset.UtcNow);
        log.Add(run);
        return TypedResults.Ok(run);
    }

    // 4. ValueTask<T>: a cache hit completes synchronously → no Task allocation at all.
    private static async Task<IResult> ValueTaskAsync(string key, PriceCache cache)
    {
        if (string.IsNullOrWhiteSpace(key) || key.Length > 32)
            return TypedResults.BadRequest(new { error = "key is required (≤ 32 chars)." });

        var sw = Stopwatch.StartNew();
        var pending = cache.GetPriceAsync(key);
        var sync = pending.IsCompletedSuccessfully;   // inspect BEFORE awaiting…
        var value = await pending;                    // …and await exactly once
        var ms = sw.Elapsed.TotalMilliseconds;

        var (taskBytes, valueTaskBytes) = await PriceCache.MeasureHotPathAllocationsAsync(Iterations);
        return TypedResults.Ok(new ValueTaskResult(key, value, sync, Math.Round(ms, 3), taskBytes, valueTaskBytes, Iterations));
    }

    private static async Task<IoCall> SimulatedIoAsync(string name, int delayMs, CancellationToken ct)
    {
        var before = Environment.CurrentManagedThreadId;
        // No thread is blocked here: Task.Delay registers a timer and the method RETURNS to its caller.
        // When the timer fires, the rest of the method (the continuation) runs on any pool thread.
        await Task.Delay(delayMs, ct);
        return new IoCall(name, delayMs, before, Environment.CurrentManagedThreadId);
    }

    private static async IAsyncEnumerable<StreamItem> ProduceAsync(int count, int delayMs, [EnumeratorCancellation] CancellationToken ct)
    {
        for (var i = 1; i <= count; i++)
        {
            await Task.Delay(delayMs, ct);   // stop producing as soon as the client disconnects
            yield return new StreamItem(i, DateTimeOffset.UtcNow, Environment.CurrentManagedThreadId);
        }
    }
}

/// <summary>
/// Singleton shared by every request → must be thread-safe. C# 13 <see cref="Lock"/>: a dedicated
/// lock type (faster than lock(object), and the compiler warns if you lock on it the wrong way).
/// </summary>
public sealed class SlowRunLog
{
    private const int Capacity = 20;
    private readonly Lock _gate = new();
    private readonly LinkedList<SlowRun> _runs = new();

    public void Add(SlowRun run)
    {
        lock (_gate)
        {
            _runs.AddFirst(run);
            if (_runs.Count > Capacity) _runs.RemoveLast();
        }
    }

    public IReadOnlyList<SlowRun> Recent()
    {
        lock (_gate) return [.. _runs];   // copy inside the lock: never hand out the live collection
    }
}

/// <summary>Hot path that usually completes synchronously: the textbook ValueTask use case.</summary>
public sealed class PriceCache(IMemoryCache cache)
{
    public ValueTask<decimal> GetPriceAsync(string key) =>
        cache.TryGetValue($"price:{key}", out decimal price)
            ? ValueTask.FromResult(price)                     // hit: no allocation, no state machine
            : new ValueTask<decimal>(LoadAndCacheAsync(key)); // miss: wraps a real Task

    private async Task<decimal> LoadAndCacheAsync(string key)
    {
        await Task.Delay(300); // simulate the database
        var price = Math.Round(10 + (decimal)Random.Shared.NextDouble() * 90, 2);
        cache.Set($"price:{key}", price, TimeSpan.FromSeconds(30));
        return price;
    }

    // Same synchronous result returned N times as Task<T> then as ValueTask<T>: count the bytes.
    public static async Task<(long TaskBytes, long ValueTaskBytes)> MeasureHotPathAllocationsAsync(int iterations)
    {
        long sum = 0;
        var before = GC.GetAllocatedBytesForCurrentThread();
        for (var i = 0; i < iterations; i++) sum += await CachedAsTaskAsync(i);
        var taskBytes = GC.GetAllocatedBytesForCurrentThread() - before;

        before = GC.GetAllocatedBytesForCurrentThread();
        for (var i = 0; i < iterations; i++) sum += await CachedAsValueTaskAsync(i);
        var valueTaskBytes = GC.GetAllocatedBytesForCurrentThread() - before;

        GC.KeepAlive(sum);
        return (taskBytes, valueTaskBytes);
    }

    // Plain (non-async) methods on purpose: an async method's state machine is a class in Debug
    // builds, which would blur the comparison. Task.FromResult allocates a Task<int> per call
    // (only a few tiny values are cached by the runtime); a ValueTask<int> holding a result is a struct.
    private static Task<int> CachedAsTaskAsync(int i) => Task.FromResult(1000 + i);
    private static ValueTask<int> CachedAsValueTaskAsync(int i) => ValueTask.FromResult(1000 + i);
}

using System.Diagnostics;
using System.Threading.Channels;

namespace DevLab.Api.Features.AsyncConcurrency;

public record JobSpan(int Job, long StartMs, long EndMs, int InFlightAtStart);
public record ThrottleResult(int MaxConcurrency, int ObservedMaxInFlight, long TotalMs, IReadOnlyList<JobSpan> Jobs);
public record ChannelEvent(long AtMs, string Kind, int Item, int Buffered);
public record ChannelResult(int Capacity, int ProducerWaits, long TotalMs, IReadOnlyList<ChannelEvent> Events);
public record RaceResult(string Mode, int Expected, int Actual, int Lost, double Ms, int ProcessorCount);

/// <summary>Throttling, producer/consumer and race conditions — the three classics.</summary>
internal static class ConcurrencyDemos
{
    public static void Map(RouteGroupBuilder group)
    {
        group.MapGet("/throttle", (int? max, CancellationToken ct) => ThrottleAsync(Math.Clamp(max ?? 3, 1, 20), ct));

        group.MapGet("/channel", (int? capacity, int? items, int? producerDelayMs, int? consumerDelayMs, CancellationToken ct) =>
            ChannelAsync(Math.Clamp(capacity ?? 3, 1, 10), Math.Clamp(items ?? 10, 1, 20),
                Math.Clamp(producerDelayMs ?? 50, 0, 300), Math.Clamp(consumerDelayMs ?? 200, 0, 300), ct));

        group.MapGet("/race", (int? n) => TypedResults.Ok(Race(Math.Clamp(n ?? 10_000, 1_000, 1_000_000))));
    }

    // ── SemaphoreSlim: at most K jobs inside the critical section at any time ─────────────────
    private static async Task<ThrottleResult> ThrottleAsync(int max, CancellationToken ct)
    {
        using var semaphore = new SemaphoreSlim(max, max);
        var inFlight = 0;
        var observedMax = 0;
        var sw = Stopwatch.StartNew();

        async Task<JobSpan> RunJobAsync(int job)
        {
            await semaphore.WaitAsync(ct);        // async wait: no thread is parked while queued
            try
            {
                var now = Interlocked.Increment(ref inFlight);
                InterlockedMax(ref observedMax, now);
                var start = sw.ElapsedMilliseconds;
                await Task.Delay(150, ct);        // the throttled I/O (an external API with a quota…)
                return new JobSpan(job, start, sw.ElapsedMilliseconds, now);
            }
            finally
            {
                Interlocked.Decrement(ref inFlight);
                semaphore.Release();              // ALWAYS in finally, or a failing job leaks a slot forever
            }
        }

        var jobs = await Task.WhenAll(Enumerable.Range(1, 20).Select(RunJobAsync));
        return new ThrottleResult(max, observedMax, sw.ElapsedMilliseconds, jobs);
    }

    // Lock-free "max": retry the compare-and-swap until nobody changed the value under us.
    private static void InterlockedMax(ref int target, int value)
    {
        int current;
        while (value > (current = Volatile.Read(ref target)) &&
               Interlocked.CompareExchange(ref target, value, current) != current)
        {
            // another thread won the race: re-read and retry
        }
    }

    // ── Channel<T>: bounded queue between a producer and a consumer (backpressure) ────────────
    private static async Task<ChannelResult> ChannelAsync(int capacity, int items, int producerDelay, int consumerDelay, CancellationToken ct)
    {
        // Wait = when the buffer is full, WriteAsync does not complete until the consumer reads.
        // The same building block sits behind a BackgroundService work queue.
        var channel = Channel.CreateBounded<int>(new BoundedChannelOptions(capacity)
        {
            FullMode = BoundedChannelFullMode.Wait,
            SingleReader = true,
            SingleWriter = true,
        });
        var events = new List<ChannelEvent>();
        var gate = new Lock();   // producer and consumer both append to the timeline
        var sw = Stopwatch.StartNew();
        var waits = 0;

        void Record(string kind, int item)
        {
            lock (gate) events.Add(new ChannelEvent(sw.ElapsedMilliseconds, kind, item, channel.Reader.Count));
        }

        var producer = Task.Run(async () =>
        {
            for (var i = 1; i <= items; i++)
            {
                if (producerDelay > 0) await Task.Delay(producerDelay, ct);
                if (!channel.Writer.TryWrite(i))          // buffer full → we are going to WAIT
                {
                    waits++;
                    Record("blocked", i);
                    await channel.Writer.WriteAsync(i, ct);
                }
                Record("produced", i);
            }
            channel.Writer.Complete();                    // tells the consumer "no more items"
        }, ct);

        var consumer = Task.Run(async () =>
        {
            await foreach (var item in channel.Reader.ReadAllAsync(ct))
            {
                Record("consumed", item);
                if (consumerDelay > 0) await Task.Delay(consumerDelay, ct);   // slow processing
            }
        }, ct);

        await Task.WhenAll(producer, consumer);
        lock (gate) return new ChannelResult(capacity, waits, sw.ElapsedMilliseconds, [.. events]);
    }

    // ── Race condition: an increment is three steps (read, add, write) another thread can interleave ──
    private static RaceResult[] Race(int n)
    {
        var options = new ParallelOptions { MaxDegreeOfParallelism = Math.Max(4, Environment.ProcessorCount) };

        var unsafeCounter = 0;
        var ms1 = Time(() => Parallel.For(0, n, options, _ => unsafeCounter++));   // ← the bug: no analyzer catches it

        var atomic = 0;
        var ms2 = Time(() => Parallel.For(0, n, options, _ => Interlocked.Increment(ref atomic)));

        var locked = 0;
        var gate = new Lock();
        var ms3 = Time(() => Parallel.For(0, n, options, _ => { lock (gate) locked++; }));

        return
        [
            new("counter++", n, unsafeCounter, n - unsafeCounter, ms1, Environment.ProcessorCount),
            new("Interlocked", n, atomic, n - atomic, ms2, Environment.ProcessorCount),
            new("lock", n, locked, n - locked, ms3, Environment.ProcessorCount),
        ];
    }

    private static double Time(Action action)
    {
        var sw = Stopwatch.StartNew();
        action();
        return Math.Round(sw.Elapsed.TotalMilliseconds, 2);
    }
}

using System.Diagnostics;

namespace DevLab.Api.Features.AsyncConcurrency;

public record ThreadPoolSnapshot(int ThreadCount, long PendingWorkItems, long CompletedWorkItems,
    int AvailableWorkerThreads, int AvailableIoThreads, int MinWorkerThreads, int MaxWorkerThreads, int ProcessorCount);
public record ThreadPoolLoadResult(string Mode, int N, int Ms, long TotalMs, double AvgStartDelayMs, double MaxStartDelayMs,
    int PeakThreadCount, long PeakPendingWorkItems, ThreadPoolSnapshot Before, ThreadPoolSnapshot After);

/// <summary>
/// Thread-pool starvation, made visible. N work items each "wait" ms milliseconds, three ways:
///  - async           : await Task.Delay → the thread goes back to the pool immediately.
///  - sleep           : Thread.Sleep → the thread is held hostage; the pool must inject new threads (slowly).
///  - sync-over-async : Task.Delay(ms).Wait() → same hostage situation (the pool detects it and injects a bit faster).
/// Safety on a shared instance: N ≤ 50, ms ≤ 2000, and only one run at a time.
/// </summary>
public sealed class ThreadPoolDemo : IDisposable
{
    private static readonly string[] Modes = ["async", "sleep", "sync-over-async"];
    private readonly SemaphoreSlim _oneRunAtATime = new(1, 1);

    public static void Map(RouteGroupBuilder group)
    {
        group.MapGet("/threadpool", () => TypedResults.Ok(Snapshot()));

        group.MapPost("/threadpool/load", async Task<IResult> (string mode, int? n, int? ms, ThreadPoolDemo demo) =>
        {
            if (!Modes.Contains(mode))
                return TypedResults.BadRequest(new { error = $"mode must be one of: {string.Join(", ", Modes)}" });

            if (!await demo._oneRunAtATime.WaitAsync(0))   // never stack two starvation runs
                return TypedResults.Conflict(new { error = "A thread-pool run is already in progress, retry in a few seconds." });
            try
            {
                return TypedResults.Ok(await RunAsync(mode, Math.Clamp(n ?? 20, 1, 50), Math.Clamp(ms ?? 1000, 50, 2000)));
            }
            finally
            {
                demo._oneRunAtATime.Release();
            }
        });
    }

    public static ThreadPoolSnapshot Snapshot()
    {
        ThreadPool.GetAvailableThreads(out var worker, out var io);
        ThreadPool.GetMinThreads(out var minWorker, out _);
        ThreadPool.GetMaxThreads(out var maxWorker, out _);
        return new ThreadPoolSnapshot(ThreadPool.ThreadCount, ThreadPool.PendingWorkItemCount, ThreadPool.CompletedWorkItemCount,
            worker, io, minWorker, maxWorker, Environment.ProcessorCount);
    }

    private static async Task<ThreadPoolLoadResult> RunAsync(string mode, int n, int ms)
    {
        var before = Snapshot();
        var sw = Stopwatch.StartNew();
        var startDelays = new double[n];

        // Start delay = time between "queued" and "a pool thread actually picked it up".
        // That queueing time is exactly what every other request suffers during starvation.
        var work = Enumerable.Range(0, n).Select(i =>
        {
            var queuedAt = sw.Elapsed.TotalMilliseconds;
            return mode switch
            {
                "async" => Task.Run(async () =>
                {
                    startDelays[i] = sw.Elapsed.TotalMilliseconds - queuedAt;
                    await Task.Delay(ms);
                }),
                "sleep" => Task.Run(() =>
                {
                    startDelays[i] = sw.Elapsed.TotalMilliseconds - queuedAt;
                    Thread.Sleep(ms);
                }),
                _ => Task.Run(() =>
                {
                    startDelays[i] = sw.Elapsed.TotalMilliseconds - queuedAt;
                    Task.Delay(ms).Wait();   // the anti-pattern on purpose: a pool thread blocked on async work
                }),
            };
        }).ToArray();

        var all = Task.WhenAll(work);
        int peakThreads = 0;
        long peakPending = 0;
        do
        {
            await Task.WhenAny(all, Task.Delay(50));   // sample every 50 ms (skips the instant enqueue burst)
            peakThreads = Math.Max(peakThreads, ThreadPool.ThreadCount);
            peakPending = Math.Max(peakPending, ThreadPool.PendingWorkItemCount);
        } while (!all.IsCompleted);
        await all;

        return new ThreadPoolLoadResult(mode, n, ms, sw.ElapsedMilliseconds,
            Math.Round(startDelays.Average(), 1), Math.Round(startDelays.Max(), 1),
            Math.Max(peakThreads, ThreadPool.ThreadCount), peakPending, before, Snapshot());
    }

    public void Dispose() => _oneRunAtATime.Dispose();
}

