using System.Diagnostics;
using DevLab.Api.Features.Products;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;
using Microsoft.EntityFrameworkCore;

namespace DevLab.Api.Features.Observability;

public record CheckoutResult(string OrderId, string TraceId, string Outcome, double DurationMs, decimal Total);

public sealed class PaymentDeclinedException(string message) : Exception(message);

/// <summary>
/// A fake checkout in four steps. Each step is a span (Activity) nested under "checkout",
/// itself nested under the ASP.NET Core server span — the waterfall you see in the lesson.
/// </summary>
public sealed class CheckoutSimulator(
    AppDbContext db,
    IHttpClientFactory httpClientFactory,
    IServer server,
    CheckoutMetrics metrics,
    ILogger<CheckoutSimulator> logger)
{
    // One ActivitySource per component, named like a namespace; registered with AddSource(...).
    // Static: an ActivitySource is cheap, thread-safe and lives as long as the process.
    public static readonly ActivitySource Source = new(CheckoutMetrics.MeterName, "1.0.0");

    public async Task<CheckoutResult> RunAsync(bool failPayment, CancellationToken ct)
    {
        var orderId = $"ORD-{Random.Shared.Next(1000, 9999)}";
        var started = Stopwatch.GetTimestamp();

        // A scope adds OrderId to EVERY log line written inside it, without repeating it in each message.
        using var scope = logger.BeginScope(new Dictionary<string, object> { ["OrderId"] = orderId });

        // StartActivity returns null when nobody listens (no OpenTelemetry) or the trace is not sampled:
        // hence the ?. everywhere — instrumentation must never cost anything when it is off.
        using var checkout = Source.StartActivity("checkout");
        checkout?.SetTag("order.id", orderId);
        logger.LogInformation("Checkout {OrderId} started", orderId);

        try
        {
            await ValidateCartAsync(ct);
            var products = await LoadProductsAsync(ct);
            await ReserveStockAsync(products[0].Id, ct);
            var total = products.Sum(p => p.Price);
            await ChargePaymentAsync(orderId, total, failPayment, ct);

            checkout?.SetStatus(ActivityStatusCode.Ok);
            var ms = Stopwatch.GetElapsedTime(started).TotalMilliseconds;
            metrics.Record("success", ms);
            logger.LogInformation("Checkout {OrderId} completed in {ElapsedMs:F0} ms for {Total} EUR", orderId, ms, total);
            return new CheckoutResult(orderId, checkout?.TraceId.ToHexString() ?? "", "success", ms, total);
        }
        catch (PaymentDeclinedException ex)
        {
            checkout?.SetStatus(ActivityStatusCode.Error, ex.Message);
            var ms = Stopwatch.GetElapsedTime(started).TotalMilliseconds;
            metrics.Record("payment_declined", ms);
            logger.LogWarning(ex, "Checkout {OrderId} failed: {Reason}", orderId, ex.Message);
            return new CheckoutResult(orderId, checkout?.TraceId.ToHexString() ?? "", "payment_declined", ms, 0);
        }
    }

    private static async Task ValidateCartAsync(CancellationToken ct)
    {
        using var span = Source.StartActivity("validate-cart");
        span?.SetTag("cart.items", 3);
        await Task.Delay(Random.Shared.Next(10, 25), ct);
        // An event = a timestamped point inside a span (cheaper than a child span).
        span?.AddEvent(new ActivityEvent("cart.validated"));
    }

    private async Task<List<Product>> LoadProductsAsync(CancellationToken ct)
    {
        // EF Core emits no spans by itself (OpenTelemetry.Instrumentation.EntityFrameworkCore is still
        // beta): we wrap the query by hand, with the OpenTelemetry semantic-convention tag names.
        using var span = Source.StartActivity("db.query products", ActivityKind.Client);
        var query = db.Products.AsNoTracking().OrderBy(p => p.Id).Take(3);
        span?.SetTag("db.system.name", "sqlite");
        span?.SetTag("db.query.text", query.ToQueryString());
        var products = await query.ToListAsync(ct);
        span?.SetTag("db.response.returned_rows", products.Count);
        return products;
    }

    private async Task ReserveStockAsync(int productId, CancellationToken ct)
    {
        using var span = Source.StartActivity("reserve-stock");
        span?.SetTag("product.id", productId);
        // A real HTTP call (to ourselves): HttpClient instrumentation adds a CLIENT span and injects
        // the `traceparent` header, the inventory endpoint continues the SAME trace (SERVER span).
        var client = httpClientFactory.CreateClient(ObservabilityLesson.InventoryClient);
        using var response = await client.GetAsync(new Uri(SelfBaseUri(), $"/api/observability/inventory/{productId}"), ct);
        response.EnsureSuccessStatusCode();
    }

    private static async Task ChargePaymentAsync(string orderId, decimal total, bool fail, CancellationToken ct)
    {
        using var span = Source.StartActivity("charge-payment", ActivityKind.Client);
        span?.SetTag("payment.provider", "fake-psp");
        span?.SetTag("payment.amount", total);
        await Task.Delay(Random.Shared.Next(40, 120), ct);
        if (!fail) return;

        var ex = new PaymentDeclinedException($"Card declined for {orderId}");
        // Status Error + an "exception" event (type, message, stack): what the dashboards turn red.
        span?.SetStatus(ActivityStatusCode.Error, ex.Message);
        span?.AddException(ex);
        throw ex;
    }

    /// <summary>Loopback address of this very process (Kestrel), whatever the public host name is.</summary>
    private Uri SelfBaseUri()
    {
        var address = server.Features.Get<IServerAddressesFeature>()?.Addresses
            .FirstOrDefault(a => a.StartsWith("http://", StringComparison.Ordinal)) ?? "http://localhost";
        var uri = new UriBuilder(address.Replace("://+", "://localhost").Replace("://*", "://localhost")
            .Replace("://[::]", "://localhost").Replace("://0.0.0.0", "://localhost"));
        return uri.Uri;
    }
}

using Microsoft.AspNetCore.Http.Features;
using OpenTelemetry.Logs;
using OpenTelemetry.Metrics;
using OpenTelemetry.Trace;

namespace DevLab.Api.Features.Observability;

/// <summary>
/// Plugs the lesson into the OpenTelemetry pipeline that AddServiceDefaults() created:
/// our ActivitySource and Meter, plus two in-memory processors feeding the in-app trace viewer.
/// The OTLP exporter (Aspire dashboard, Jaeger, Grafana…) receives exactly the same data.
/// </summary>
public static class ObservabilityLesson
{
    public const string InventoryClient = "inventory";

    public static IServiceCollection AddObservabilityLesson(this IServiceCollection services)
    {
        services.AddSingleton<TelemetryStore>();
        services.AddSingleton<CheckoutMetrics>();
        services.AddSingleton<InAppMetricsListener>();
        services.AddScoped<CheckoutSimulator>();
        services.AddHttpClient(InventoryClient);

        // Configure* = "add to the provider, whoever builds it" — no second AddOpenTelemetry() call needed.
        services.ConfigureOpenTelemetryTracerProvider(t => t
            .AddSource(CheckoutMetrics.MeterName)
            .AddProcessor(sp => new InMemorySpanProcessor(sp.GetRequiredService<TelemetryStore>())));
        services.ConfigureOpenTelemetryMeterProvider(m => m.AddMeter(CheckoutMetrics.MeterName));
        services.ConfigureOpenTelemetryLoggerProvider(l => l
            .AddProcessor(sp => new InMemoryLogProcessor(sp.GetRequiredService<TelemetryStore>())));
        return services;
    }

    /// <summary>
    /// Echoes the server span's W3C context in a response header, so the browser (and you, in the
    /// network panel) can see which trace a response belongs to. W3C Trace Context Level 2 drafts
    /// a dedicated `traceresponse` header for this; the lab reuses the familiar `traceparent` name.
    /// </summary>
    public static IApplicationBuilder UseTraceparentResponseHeader(this IApplicationBuilder app) =>
        app.Use((ctx, next) =>
        {
            var activity = ctx.Features.Get<IHttpActivityFeature>()?.Activity;
            if (activity is not null)
                ctx.Response.OnStarting(() =>
                {
                    ctx.Response.Headers["traceparent"] = activity.Id;
                    return Task.CompletedTask;
                });
            return next(ctx);
        });

    public static IEndpointRouteBuilder MapObservabilityEndpoints(this IEndpointRouteBuilder app)
    {
        // Created now, not on first use: a MeterListener only sees measurements made after it starts.
        app.ServiceProvider.GetRequiredService<InAppMetricsListener>();

        var group = app.MapGroup("/api/observability").WithTags("Observability");

        // ?fail=true → the payment step fails: a red span, an exception event, a Warning log.
        group.MapPost("/checkout", async (bool? fail, CheckoutSimulator simulator, CancellationToken ct) =>
            TypedResults.Ok(await simulator.RunAsync(fail ?? false, ct)));

        // Called BY the checkout over HTTP: its server span is a child of the HttpClient span.
        group.MapGet("/inventory/{productId:int}", async (int productId, HttpRequest request, ILogger<CheckoutSimulator> logger, CancellationToken ct) =>
        {
            await Task.Delay(Random.Shared.Next(15, 40), ct);
            logger.LogInformation("Stock reserved for product {ProductId} (incoming traceparent {Traceparent})",
                productId, request.Headers.TraceParent.ToString());
            return TypedResults.Ok(new { productId, reserved = true, traceparent = request.Headers.TraceParent.ToString() });
        });

        // ?traceId= looks one trace up, like a trace backend's search: the "recent" list alone
        // can push it out when other traffic (or parallel test hosts) is also being traced.
        group.MapGet("/traces", (TelemetryStore store, int? limit, string? traceId) =>
            TypedResults.Ok(store.RecentTraces(Math.Clamp(limit ?? 8, 1, 30), traceId)));

        group.MapGet("/metrics", (InAppMetricsListener listener) => TypedResults.Ok(listener.Snapshot()));

        return app;
    }
}

using System.Diagnostics;
using System.Diagnostics.Metrics;
using OpenTelemetry;
using OpenTelemetry.Logs;

namespace DevLab.Api.Features.Observability;

public record SpanEvent(string Name, DateTime Timestamp, IReadOnlyDictionary<string, string?> Tags);

public record SpanRecord(
    string TraceId, string SpanId, string? ParentSpanId, string Name, string Source, string Kind,
    DateTime StartUtc, double DurationMs, string Status, string? StatusDescription,
    IReadOnlyDictionary<string, string?> Tags, IReadOnlyList<SpanEvent> Events);

public record LogLine(
    DateTime Timestamp, string Level, string Category, string Message,
    string? TraceId, string? SpanId, IReadOnlyDictionary<string, string?> Scopes);

public record TraceView(string TraceId, string Root, DateTime StartUtc, double DurationMs, bool HasError,
    IReadOnlyList<SpanRecord> Spans, IReadOnlyList<LogLine> Logs);

/// <summary>
/// The in-app "backend" of the trace viewer: two bounded ring buffers (spans, logs).
/// A real system exports to Jaeger / Tempo / the Aspire dashboard; this one keeps the last
/// few hundred items in memory so the lesson works on a free single-instance deployment.
/// </summary>
public sealed class TelemetryStore
{
    private const int MaxSpans = 400;
    private const int MaxLogs = 400;
    private readonly Lock _gate = new();
    private readonly Queue<SpanRecord> _spans = new();
    private readonly Queue<LogLine> _logs = new();

    public void Add(SpanRecord span)
    {
        lock (_gate)
        {
            _spans.Enqueue(span);
            while (_spans.Count > MaxSpans) _spans.Dequeue();
        }
    }

    public void Add(LogLine log)
    {
        lock (_gate)
        {
            _logs.Enqueue(log);
            while (_logs.Count > MaxLogs) _logs.Dequeue();
        }
    }

    /// <summary>Groups spans by TraceId (what a trace backend does) and joins the logs on the same id.</summary>
    public IReadOnlyList<TraceView> RecentTraces(int limit, string? traceId = null)
    {
        SpanRecord[] spans;
        LogLine[] logs;
        lock (_gate)
        {
            spans = [.. _spans];
            logs = [.. _logs];
        }

        return [.. spans
            .Where(s => traceId is null || string.Equals(s.TraceId, traceId, StringComparison.Ordinal))
            .GroupBy(s => s.TraceId)
            .Select(g =>
            {
                var ordered = g.OrderBy(s => s.StartUtc).ToList();
                var start = ordered[0].StartUtc;
                var end = ordered.Max(s => s.StartUtc.AddMilliseconds(s.DurationMs));
                // The root is the span whose parent is not in this process's buffer (the browser, or nothing).
                var ids = ordered.Select(s => s.SpanId).ToHashSet(StringComparer.Ordinal);
                var root = ordered.FirstOrDefault(s => s.ParentSpanId is null || !ids.Contains(s.ParentSpanId)) ?? ordered[0];
                return new TraceView(g.Key, root.Name, start, (end - start).TotalMilliseconds,
                    ordered.Exists(s => s.Status == "Error"),
                    ordered,
                    [.. logs.Where(l => l.TraceId == g.Key).OrderBy(l => l.Timestamp)]);
            })
            .OrderByDescending(t => t.StartUtc)
            .Take(limit)];
    }
}

/// <summary>
/// An OpenTelemetry processor sees every span when it ENDS (OnEnd). Exporters are processors
/// too (BatchExportProcessor → OTLP); this one just copies the span into the in-memory store.
/// Only sampled spans (Recorded = true) reach it: that is where sampling shows up.
/// </summary>
public sealed class InMemorySpanProcessor(TelemetryStore store) : BaseProcessor<Activity>
{
    // The viewer polls these: recording them would push the interesting traces out of the buffer.
    private static readonly string[] IgnoredPaths = ["/api/observability/traces", "/api/observability/metrics", "/api/source"];

    public override void OnEnd(Activity data)
    {
        var path = data.GetTagItem("url.path") as string;
        if (path is not null && IgnoredPaths.Any(p => path.StartsWith(p, StringComparison.Ordinal))) return;

        store.Add(new SpanRecord(
            data.TraceId.ToHexString(),
            data.SpanId.ToHexString(),
            data.ParentSpanId == default ? null : data.ParentSpanId.ToHexString(),
            data.DisplayName,
            data.Source.Name,
            data.Kind.ToString(),
            data.StartTimeUtc,
            data.Duration.TotalMilliseconds,
            data.Status.ToString(),
            data.StatusDescription,
            data.TagObjects.ToDictionary(t => t.Key, t => t.Value?.ToString(), StringComparer.Ordinal),
            [.. data.Events.Select(e => new SpanEvent(e.Name, e.Timestamp.UtcDateTime,
                e.Tags.ToDictionary(t => t.Key, t => t.Value?.ToString(), StringComparer.Ordinal)))]));
    }
}

/// <summary>
/// Same idea for logs: every ILogger call becomes a LogRecord carrying the TraceId/SpanId of the
/// Activity that was current when it was written — the log ↔ trace correlation, for free.
/// </summary>
public sealed class InMemoryLogProcessor(TelemetryStore store) : BaseProcessor<LogRecord>
{
    public override void OnEnd(LogRecord data)
    {
        // Only keep logs that belong to a trace and come from the app (not Kestrel/EF chatter).
        if (data.TraceId == default || data.CategoryName?.StartsWith("DevLab", StringComparison.Ordinal) != true) return;

        var scopes = new Dictionary<string, string?>(StringComparer.Ordinal);
        data.ForEachScope((scope, state) =>
        {
            // Hosting's own scope repeats SpanId/TraceId/ParentId: already first-class fields of the record.
            foreach (var kv in scope)
                if (kv.Key is not ("SpanId" or "TraceId" or "ParentId")) state[kv.Key] = kv.Value?.ToString();
        }, scopes);

        store.Add(new LogLine(
            data.Timestamp,
            data.LogLevel.ToString(),
            data.CategoryName,
            data.FormattedMessage ?? data.Body ?? "",
            data.TraceId.ToHexString(),
            data.SpanId.ToHexString(),
            scopes));
    }
}

/// <summary>
/// Custom metrics, the .NET 8+ way: the Meter comes from IMeterFactory (one per DI container,
/// testable), instruments are created once, tags carry the dimensions (outcome=success…).
/// </summary>
public sealed class CheckoutMetrics
{
    public const string MeterName = "DevLab.Observability";
    private readonly Counter<long> _checkouts;
    private readonly Histogram<double> _duration;

    public CheckoutMetrics(IMeterFactory meterFactory)
    {
        Meter = meterFactory.Create(MeterName, "1.0.0");
        _checkouts = Meter.CreateCounter<long>("devlab.checkout.count", "{checkout}", "Checkouts processed, by outcome.");
        _duration = Meter.CreateHistogram<double>("devlab.checkout.duration", "ms", "End-to-end checkout duration.");
    }

    public Meter Meter { get; }

    public void Record(string outcome, double elapsedMs)
    {
        var tag = new KeyValuePair<string, object?>("outcome", outcome);
        _checkouts.Add(1, tag);
        _duration.Record(elapsedMs, tag);
    }
}

public record MetricPoint(string Instrument, string Outcome, long Count, double Sum, double Min, double Max);

/// <summary>
/// A MeterListener is what an exporter uses under the hood: subscribe to instruments, receive
/// every measurement, aggregate. Here: count / sum / min / max per (instrument, outcome).
/// </summary>
public sealed class InAppMetricsListener : IDisposable
{
    private readonly MeterListener _listener = new();
    private readonly Lock _gate = new();
    private readonly Dictionary<(string Instrument, string Outcome), MetricPoint> _points = [];

    public InAppMetricsListener(CheckoutMetrics metrics)
    {
        _listener.InstrumentPublished = (instrument, listener) =>
        {
            // ReferenceEquals: only THIS container's meter (tests run several apps in one process).
            if (ReferenceEquals(instrument.Meter, metrics.Meter)) listener.EnableMeasurementEvents(instrument);
        };
        _listener.SetMeasurementEventCallback<long>((i, v, tags, _) => Accumulate(i.Name, v, tags));
        _listener.SetMeasurementEventCallback<double>((i, v, tags, _) => Accumulate(i.Name, v, tags));
        _listener.Start();
    }

    public IReadOnlyList<MetricPoint> Snapshot()
    {
        lock (_gate) return [.. _points.Values.OrderBy(p => p.Instrument, StringComparer.Ordinal).ThenBy(p => p.Outcome, StringComparer.Ordinal)];
    }

    private void Accumulate(string instrument, double value, ReadOnlySpan<KeyValuePair<string, object?>> tags)
    {
        var outcome = "";
        foreach (var t in tags) if (t.Key == "outcome") outcome = t.Value?.ToString() ?? "";

        lock (_gate)
        {
            var key = (instrument, outcome);
            _points[key] = _points.TryGetValue(key, out var p)
                ? p with { Count = p.Count + 1, Sum = p.Sum + value, Min = Math.Min(p.Min, value), Max = Math.Max(p.Max, value) }
                : new MetricPoint(instrument, outcome, 1, value, value, value);
        }
    }

    public void Dispose() => _listener.Dispose();
}

