using System.Buffers;
using System.Globalization;
using System.Runtime.CompilerServices;

namespace DevLab.Api.Features.Performance;

/// <summary>
/// The same work written twice: once the "natural" way, once allocation-free.
/// The results are identical; only what the GC has to clean up differs.
/// </summary>
public static class AllocationWorkloads
{
    public const string CsvLine = "1042,7,250,2026,13,99,3,18";
    public const int BufferSize = 4096;
    // Just above the 85 000-byte threshold: every array goes straight to the Large Object Heap.
    public const int LargeBufferSize = 90_000;

    // Each field becomes a new string on the heap (≈ 30 bytes) that dies immediately.
#pragma warning disable CA1846 // the allocating Substring IS the point of the comparison
    public static long ParseWithSubstring(string line)
    {
        long sum = 0;
        var start = 0;
        while (true)
        {
            var comma = line.IndexOf(',', start);
            var field = comma < 0 ? line.Substring(start) : line.Substring(start, comma - start);
            sum += int.Parse(field, CultureInfo.InvariantCulture);
            if (comma < 0) return sum;
            start = comma + 1;
        }
    }
#pragma warning restore CA1846

    // A span is a (pointer, length) view over the original string: slicing copies nothing.
    public static long ParseWithSpan(ReadOnlySpan<char> line)
    {
        long sum = 0;
        while (true)
        {
            var comma = line.IndexOf(',');
            var field = comma < 0 ? line : line[..comma];
            sum += int.Parse(field, CultureInfo.InvariantCulture);
            if (comma < 0) return sum;
            line = line[(comma + 1)..];
        }
    }

    public static long WithNewArray(int size) => Fill(new byte[size], size);

    // Rent may return a LARGER array than asked: always work on [0..size), and give it back in finally.
    public static long WithPooledArray(int size)
    {
        var buffer = ArrayPool<byte>.Shared.Rent(size);
        try
        {
            return Fill(buffer, size);
        }
        finally
        {
            ArrayPool<byte>.Shared.Return(buffer);
        }
    }

    // NoInlining: the array escapes into a real call, so the .NET 10 JIT cannot stack-allocate it
    // (escape analysis) and silently erase the difference we want to show.
    [MethodImpl(MethodImplOptions.NoInlining)]
    private static long Fill(byte[] buffer, int size)
    {
        var span = buffer.AsSpan(0, size);
        span.Fill(0x2A);
        return span[0] + span[^1] + size;
    }
}

using System.Diagnostics.Metrics;

namespace DevLab.Api.Features.Performance;

/// <summary>
/// Custom metrics on the "DevLab" Meter. Nothing to export: <c>dotnet-counters monitor
/// --counters DevLab,System.Runtime -n DevLab.Api</c> attaches to the process and reads them live
/// (EventPipe). The same instruments would flow to OpenTelemetry / Prometheus unchanged.
/// </summary>
public sealed class PerfMetrics
{
    public const string MeterName = "DevLab";

    private readonly Counter<long> _runs;
    private readonly Histogram<double> _duration;
    private readonly Counter<long> _allocated;

    // IMeterFactory (not `new Meter(...)`): the meter is owned and disposed by the DI container,
    // and each WebApplicationFactory in the tests gets its own instance.
    public PerfMetrics(IMeterFactory meterFactory)
    {
        var meter = meterFactory.Create(MeterName);
        _runs = meter.CreateCounter<long>("devlab.perf.demo.runs", unit: "{run}", description: "Performance demo executions");
        _duration = meter.CreateHistogram<double>("devlab.perf.demo.duration", unit: "ms", description: "Duration of a performance demo run");
        _allocated = meter.CreateCounter<long>("devlab.perf.demo.allocated", unit: "By", description: "Bytes allocated by performance demos");
    }

    public void Record(string demo, TimeSpan elapsed, long allocatedBytes)
    {
        var tag = new KeyValuePair<string, object?>("demo", demo);
        _runs.Add(1, tag);
        _duration.Record(elapsed.TotalMilliseconds, tag);
        _allocated.Add(allocatedBytes, tag);
    }
}

using System.Diagnostics;
using System.Runtime;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using Microsoft.AspNetCore.Http.HttpResults;
using OpenTelemetry.Metrics;

namespace DevLab.Api.Features.Performance;

public record AllocationResult(
    string Mode, int Iterations, long AllocatedBytes, double BytesPerIteration, double ElapsedMs,
    int Gen0Collections, int Gen1Collections, int Gen2Collections, long Checksum);

public record GenerationInfo(string Name, long SizeAfterBytes, long FragmentationAfterBytes);

public record GcInfo(
    string Mode, bool Concurrent, string LatencyMode, bool DatasEnabled, long LargeObjectThresholdBytes,
    long HeapSizeBytes, long FragmentedBytes, long CommittedBytes, double PauseTimePercentage,
    int Gen0Collections, int Gen1Collections, int Gen2Collections, IReadOnlyList<GenerationInfo> Generations);

public record RuntimeSwitch(string Name, bool Enabled, string Source);

public record JitInfoDto(
    long CompiledMethods, long CompiledIlBytes, double CompilationTimeMs,
    bool DynamicCodeCompiled, bool Optimized, IReadOnlyList<RuntimeSwitch> Switches);

public record RuntimeInfo(
    string Framework, string Os, string Architecture, int ProcessorCount,
    long TotalAllocatedBytes, long WorkingSetBytes, GcInfo Gc, JitInfoDto Jit);

public static class PerformanceLesson
{
    private const int MaxIterations = 100_000;

    // static lambdas: no closure, cached delegate → selecting a workload allocates nothing itself.
    private static readonly Dictionary<string, Func<int, long>> Workloads = new(StringComparer.Ordinal)
    {
        ["substring"] = static n => Repeat(n, static () => AllocationWorkloads.ParseWithSubstring(AllocationWorkloads.CsvLine)),
        ["span"] = static n => Repeat(n, static () => AllocationWorkloads.ParseWithSpan(AllocationWorkloads.CsvLine)),
        ["array"] = static n => Repeat(n, static () => AllocationWorkloads.WithNewArray(AllocationWorkloads.BufferSize)),
        ["pool"] = static n => Repeat(n, static () => AllocationWorkloads.WithPooledArray(AllocationWorkloads.BufferSize)),
        ["loh"] = static n => Repeat(n, static () => AllocationWorkloads.WithNewArray(AllocationWorkloads.LargeBufferSize)),
    };

    public static IServiceCollection AddPerformanceLesson(this IServiceCollection services)
    {
        services.AddMetrics();
        services.AddSingleton<PerfMetrics>();
        // dotnet-counters reads any Meter by name; OTLP exporters only see the ones registered here.
        services.ConfigureOpenTelemetryMeterProvider(m => m.AddMeter(PerfMetrics.MeterName));
        return services;
    }

    public static IEndpointRouteBuilder MapPerformanceEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/perf").WithTags("Performance");

        // 1. Same work, two implementations: what does the GC see?
        group.MapGet("/allocations", Results<Ok<AllocationResult>, ValidationProblem> (string mode, PerfMetrics metrics, int iterations = 10_000) =>
        {
            if (!Workloads.TryGetValue(mode, out var workload))
                return TypedResults.ValidationProblem(new Dictionary<string, string[]> { ["mode"] = [$"Expected one of: {string.Join(", ", Workloads.Keys)}."] });
            if (iterations is < 1 or > MaxIterations)
                return TypedResults.ValidationProblem(new Dictionary<string, string[]> { ["iterations"] = [$"Must be between 1 and {MaxIterations}."] });

            // The handler is synchronous on purpose: the per-thread allocation counter only means
            // something if the whole workload runs on this thread (no await in between).
            var gen0 = GC.CollectionCount(0);
            var gen1 = GC.CollectionCount(1);
            var gen2 = GC.CollectionCount(2);
            var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
            var start = Stopwatch.GetTimestamp();

            var checksum = workload(iterations);

            var elapsed = Stopwatch.GetElapsedTime(start);
            var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
            metrics.Record(mode, elapsed, allocated);

            return TypedResults.Ok(new AllocationResult(
                mode, iterations, allocated, Math.Round((double)allocated / iterations, 1), Math.Round(elapsed.TotalMilliseconds, 3),
                GC.CollectionCount(0) - gen0, GC.CollectionCount(1) - gen1, GC.CollectionCount(2) - gen2, checksum));
        });

        // 2. What runtime are we on, and what has the GC been doing?
        group.MapGet("/runtime", () => TypedResults.Ok(DescribeRuntime()));

        // 3. Tiered JIT: first call vs the following ones, on a method nobody has called yet.
        //    loop=true picks a method with a loop, to see On-Stack Replacement at work instead.
        group.MapGet("/tiering", Results<Ok<TieringResult>, ValidationProblem> (PerfMetrics metrics, int durationMs = 1000, bool loop = false) =>
        {
            if (durationMs is < 50 or > 3000)
                return TypedResults.ValidationProblem(new Dictionary<string, string[]> { ["durationMs"] = ["Must be between 50 and 3000."] });

            var result = TieringDemo.Run(TimeSpan.FromMilliseconds(durationMs), loop);
            metrics.Record("tiering", TimeSpan.FromMilliseconds(result.DurationMs), 0);
            return TypedResults.Ok(result);
        });

        return app;
    }

    private static long Repeat(int n, Func<long> body)
    {
        long checksum = 0;
        for (var i = 0; i < n; i++) checksum += body();
        return checksum;
    }

    private static RuntimeInfo DescribeRuntime()
    {
        var gc = GC.GetGCMemoryInfo();
        var config = GC.GetConfigurationVariables();
        string[] generationNames = ["gen0", "gen1", "gen2", "LOH", "POH"];
        var generations = gc.GenerationInfo.ToArray()
            .Select((g, i) => new GenerationInfo(generationNames[i], g.SizeAfterBytes, g.FragmentationAfterBytes))
            .ToList();

        var gcInfo = new GcInfo(
            Mode: GCSettings.IsServerGC ? "Server" : "Workstation",
            Concurrent: config.TryGetValue("ConcurrentGC", out var concurrent) && concurrent is true,
            LatencyMode: GCSettings.LatencyMode.ToString(),
            // DATAS (dynamic heap count) is on by default since .NET 9, but only Server GC uses it.
            DatasEnabled: GCSettings.IsServerGC && config.TryGetValue("GCDynamicAdaptationMode", out var datas) && Convert.ToInt64(datas, System.Globalization.CultureInfo.InvariantCulture) == 1,
            LargeObjectThresholdBytes: config.TryGetValue("LOHThreshold", out var loh) ? Convert.ToInt64(loh, System.Globalization.CultureInfo.InvariantCulture) : 85_000,
            HeapSizeBytes: gc.HeapSizeBytes,
            FragmentedBytes: gc.FragmentedBytes,
            CommittedBytes: gc.TotalCommittedBytes,
            PauseTimePercentage: gc.PauseTimePercentage,
            Gen0Collections: GC.CollectionCount(0),
            Gen1Collections: GC.CollectionCount(1),
            Gen2Collections: GC.CollectionCount(2),
            Generations: generations);

        var jit = new JitInfoDto(
            CompiledMethods: JitInfo.GetCompiledMethodCount(currentThread: false),
            CompiledIlBytes: JitInfo.GetCompiledILBytes(currentThread: false),
            CompilationTimeMs: Math.Round(JitInfo.GetCompilationTime(currentThread: false).TotalMilliseconds, 1),
            DynamicCodeCompiled: RuntimeFeature.IsDynamicCodeCompiled,
            Optimized: TieringDemo.JitOptimized,
            Switches:
            [
                Switch("System.Runtime.TieredCompilation", "DOTNET_TieredCompilation"),
                Switch("System.Runtime.TieredCompilation.QuickJitForLoops", "DOTNET_TC_QuickJitForLoops"),
                Switch("System.Runtime.TieredPGO", "DOTNET_TieredPGO"),
                Switch("System.Runtime.ReadyToRun", "DOTNET_ReadyToRun"),
            ]);

        return new RuntimeInfo(
            RuntimeInformation.FrameworkDescription,
            RuntimeInformation.OSDescription,
            RuntimeInformation.ProcessArchitecture.ToString(),
            Environment.ProcessorCount,
            GC.GetTotalAllocatedBytes(),
            Environment.WorkingSet,
            gcInfo,
            jit);
    }

    // Precedence used by the runtime: environment variable > runtimeconfig.json (csproj property) > default.
    // All four knobs default to ON in .NET 10.
    private static RuntimeSwitch Switch(string name, string envVar)
    {
        var env = Environment.GetEnvironmentVariable(envVar);
        if (env is "0" or "1") return new RuntimeSwitch(name, env == "1", $"env {envVar}");
        if (AppContext.TryGetSwitch(name, out var enabled)) return new RuntimeSwitch(name, enabled, "runtimeconfig.json");
        return new RuntimeSwitch(name, true, "défaut");
    }
}

using System.Diagnostics;
using System.Numerics;
using System.Reflection;
using System.Runtime;

namespace DevLab.Api.Features.Performance;

// Count = calls so far (variant "call") or loop iterations so far (variant "loop").
public record TieringPoint(double AtMs, long Count, double AvgNs);

public record TieringResult(
    string Variant,
    bool JitOptimized,
    string Instantiation,
    double FirstCallUs,
    double Tier0AvgNs,
    double SteadyAvgNs,
    double Speedup,
    long Count,
    double DurationMs,
    long JitMethodsCompiled,
    double JitTimeMs,
    IReadOnlyList<TieringPoint> Timeline);

/// <summary>
/// Watches tiered compilation happen. A method is normally JIT-compiled once per process, so a
/// second run would only show warm code. Trick: <c>Work&lt;T&gt;</c> instantiated over a NEW value
/// type is a brand-new method body (value-type generics are never shared), so every run starts cold.
/// </summary>
public static class TieringDemo
{
    private const int Batch = 1_000;
    private const int Chunk = 512;
    private const int Chunks = 80;

    private static readonly Type[] Digits =
    [
        typeof(bool), typeof(byte), typeof(sbyte), typeof(short), typeof(ushort), typeof(int), typeof(uint), typeof(long),
        typeof(ulong), typeof(float), typeof(double), typeof(decimal), typeof(char), typeof(nint), typeof(nuint), typeof(Guid),
    ];

    private static int _runs = -1;

    // A Debug build marks the assembly [Debuggable(DisableOptimizations)]: its methods are JIT-compiled
    // once, unoptimized, and never tiered up. The demo is only meaningful in Release (Docker image, -c Release).
    public static bool JitOptimized { get; } =
        typeof(TieringDemo).Assembly.GetCustomAttribute<DebuggableAttribute>()?.IsJITOptimizerDisabled != true;

#pragma warning disable S2326 // T is only an identity: one instantiation = one method body to JIT
    // No loop → starts at tier-0 (no inlining, no register allocation: Math.Max and RotateLeft are real
    // calls), tier-1 only after 30 calls + the 100 ms call-counting delay, compiled in the background.
    public static long Work<T>(long x) where T : struct
    {
        x ^= x >>> 33;
        x *= unchecked((long)0xFF51AFD7ED558CCDUL);
        x = (long)BitOperations.RotateLeft((ulong)x, 17);
        x ^= x >>> 29;
        return Math.Max(x, 3) + Math.Abs(x % 7);
    }

    // A long loop in a method called ONCE: call counting can never help. Tier-0 code contains
    // patchpoints; after enough iterations the runtime compiles an optimized version of the method
    // body and jumps into it in the middle of the loop (On-Stack Replacement). The timestamps
    // written every 512 iterations show the switch.
    public static long WorkLoop<T>(long x, long[] chunkEnds) where T : struct
    {
        for (var i = 0; i < chunkEnds.Length * Chunk; i++)
        {
            x ^= x >>> 33;
            x *= unchecked((long)0xFF51AFD7ED558CCDUL);
            x = Math.Max(x, i) + Math.Abs(x % 7);
            if (i % Chunk == Chunk - 1) chunkEnds[i / Chunk] = Stopwatch.GetTimestamp();
        }
        return x;
    }
#pragma warning restore S2326

    public static TieringResult Run(TimeSpan duration, bool withLoop)
    {
        // Run n → ValueTuple<d0, d1, d2, d3> with n written in base 16: 65 536 distinct cold methods.
        var n = Interlocked.Increment(ref _runs);
        var marker = typeof(ValueTuple<,,,>).MakeGenericType(Digits[n & 15], Digits[(n >> 4) & 15], Digits[(n >> 8) & 15], Digits[(n >> 12) & 15]);
        var method = typeof(TieringDemo).GetMethod(withLoop ? nameof(WorkLoop) : nameof(Work))!.MakeGenericMethod(marker);

        // Process-wide counters: the tier-1 recompilation happens on a background thread, not ours.
        var methodsBefore = JitInfo.GetCompiledMethodCount(currentThread: false);
        var jitBefore = JitInfo.GetCompilationTime(currentThread: false);

        var (firstCallUs, coldNs, count, elapsed, timeline) = withLoop
            ? RunLoop(method.CreateDelegate<Func<long, long[], long>>(), n)
            : RunCalls(method.CreateDelegate<Func<long, long>>(), n, duration);

        var steadyNs = timeline.Count > 0 ? timeline[^1].AvgNs : coldNs;
        return new TieringResult(
            Variant: withLoop ? "loop" : "call",
            JitOptimized: JitOptimized,
            Instantiation: $"{method.Name}<{Describe(marker)}>",
            FirstCallUs: Math.Round(firstCallUs, 1),
            Tier0AvgNs: Math.Round(coldNs, 2),
            SteadyAvgNs: steadyNs,
            Speedup: steadyNs > 0 ? Math.Round(coldNs / steadyNs, 1) : 0,
            Count: count,
            DurationMs: Math.Round(elapsed.TotalMilliseconds, 1),
            JitMethodsCompiled: JitInfo.GetCompiledMethodCount(currentThread: false) - methodsBefore,
            JitTimeMs: Math.Round((JitInfo.GetCompilationTime(currentThread: false) - jitBefore).TotalMilliseconds, 2),
            Timeline: timeline);
    }

    private static (double FirstCallUs, double ColdNs, long Count, TimeSpan Elapsed, List<TieringPoint> Timeline) RunCalls(
        Func<long, long> work, long seed, TimeSpan duration)
    {
        var start = Stopwatch.GetTimestamp();
        var acc = work(seed);                                // call #1: includes the tier-0 JIT
        var firstCallUs = Stopwatch.GetElapsedTime(start).TotalMicroseconds;

        var t = Stopwatch.GetTimestamp();
        for (var i = 0; i < 29; i++) acc = work(acc);        // calls #2-#30: plain tier-0 code
        var tier0Ns = Stopwatch.GetElapsedTime(t).TotalNanoseconds / 29;

        // Then batches of 1 000 calls (timing each call would measure the Stopwatch, not the method).
        var bucket = duration / 40;
        var timeline = new List<TieringPoint>();
        long calls = 30, bucketCalls = 0;
        double bucketNs = 0;
        var bucketEnd = bucket;
        TimeSpan now;
        while ((now = Stopwatch.GetElapsedTime(start)) < duration)
        {
            t = Stopwatch.GetTimestamp();
            for (var i = 0; i < Batch; i++) acc = work(acc);
            bucketNs += Stopwatch.GetElapsedTime(t).TotalNanoseconds;
            calls += Batch;
            bucketCalls += Batch;
            if (now >= bucketEnd)
            {
                timeline.Add(new TieringPoint(Math.Round(now.TotalMilliseconds, 1), calls, Math.Round(bucketNs / bucketCalls, 2)));
                bucketNs = 0;
                bucketCalls = 0;
                bucketEnd += bucket;
            }
        }
        GC.KeepAlive(acc);
        return (firstCallUs, tier0Ns, calls, now, timeline);
    }

    private static (double FirstCallUs, double ColdNs, long Count, TimeSpan Elapsed, List<TieringPoint> Timeline) RunLoop(
        Func<long, long[], long> work, long seed)
    {
        var chunkEnds = new long[Chunks];
        var start = Stopwatch.GetTimestamp();
        GC.KeepAlive(work(seed, chunkEnds));
        var elapsed = Stopwatch.GetElapsedTime(start);

        // Chunk 0 also contains the JIT of the method itself: start the comparison at chunk 1.
        var timeline = new List<TieringPoint>(Chunks - 1);
        for (var c = 1; c < Chunks; c++)
            timeline.Add(new TieringPoint(
                Math.Round(Stopwatch.GetElapsedTime(start, chunkEnds[c]).TotalMilliseconds, 3),
                (c + 1L) * Chunk,
                Math.Round(Stopwatch.GetElapsedTime(chunkEnds[c - 1], chunkEnds[c]).TotalNanoseconds / Chunk, 2)));
        return (elapsed.TotalMicroseconds, timeline[0].AvgNs, (long)Chunks * Chunk, elapsed, timeline);
    }

    private static string Describe(Type t) =>
        t.IsGenericType ? $"({string.Join(", ", t.GetGenericArguments().Select(Describe))})" : t.Name;
}

