using DevLab.Api.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace DevLab.Api.Infrastructure.Messaging;

/// <summary>
/// Scoped "envelope" of the message being handled (what Wolverine/MassTransit call the
/// envelope or ConsumeContext): the dispatcher fills it, handlers read the id to deduplicate.
/// </summary>
public sealed class MessageContext
{
    public Guid MessageId { get; set; }
    public int Attempt { get; set; }
}

/// <summary>Lab-only fault injection: makes the next N deliveries throw, to watch retries happen.</summary>
public sealed class HandlerFaults
{
    private int _remaining;

    public int Remaining => Volatile.Read(ref _remaining);
    public void Arm(int failures) => Interlocked.Exchange(ref _remaining, Math.Clamp(failures, 0, 10));

    public void ThrowIfArmed(string handler)
    {
        // Decrement only while > 0: concurrent callers never push the counter below zero.
        int current;
        do
        {
            current = Volatile.Read(ref _remaining);
            if (current == 0) return;
        } while (Interlocked.CompareExchange(ref _remaining, current - 1, current) != current);

        throw new InvalidOperationException($"Simulated failure in {handler} ({current - 1} left)");
    }
}

public static class InboxExtensions
{
    /// <summary>
    /// Idempotent consumer: the handler's side effect and the inbox row commit together, so a
    /// redelivered message is detected and skipped. Returns false when it was a duplicate.
    /// </summary>
    public static Task<bool> HandleOnceAsync(this DbContext db, MessageContext message, string handler, Func<Task> work, CancellationToken ct) =>
        db.InTransactionAsync(async () =>
        {
            var inbox = db.Set<InboxRecord>();
            if (await inbox.AnyAsync(r => r.MessageId == message.MessageId && r.Handler == handler, ct))
                return false;

            await work();
            inbox.Add(new InboxRecord { MessageId = message.MessageId, Handler = handler });
            await db.SaveChangesAsync(ct);   // a concurrent duplicate fails here on the PK → rolled back
            return true;
        }, ct);
}

using System.Text.Json;
using DevLab.Api.Infrastructure.Events;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace DevLab.Api.Infrastructure.Messaging;

public sealed class OutboxOptions
{
    public TimeSpan PollInterval { get; set; } = TimeSpan.FromMilliseconds(500);
    public int BatchSize { get; set; } = 20;
    /// <summary>After that many failures the message is "poison": parked, no more retries, a human looks at it.</summary>
    public int MaxAttempts { get; set; } = 5;
}

/// <summary>
/// Event names are resolved against an allow-list built once, never with Type.GetType(row.Type):
/// deserializing an arbitrary type named by stored data is a classic injection vector.
/// </summary>
internal static class DomainEventTypes
{
    public static readonly IReadOnlyDictionary<string, Type> ByName = typeof(IDomainEvent).Assembly.GetTypes()
        .Where(t => typeof(IDomainEvent).IsAssignableFrom(t) && t is { IsInterface: false, IsAbstract: false })
        .ToDictionary(t => t.Name, StringComparer.Ordinal);
}

/// <summary>
/// The relay half of the outbox: polls unprocessed rows, publishes them, marks them processed.
/// Delivery is AT-LEAST-ONCE: a crash between "handler succeeded" and "row marked processed"
/// means the message is delivered again → handlers must be idempotent (see InboxExtensions).
/// </summary>
public sealed class OutboxDispatcher<TDbContext>(
    IServiceScopeFactory scopes,
    IOptions<OutboxOptions> options,
    ILogger<OutboxDispatcher<TDbContext>> logger) : BackgroundService where TDbContext : DbContext
{

    // One dispatch at a time in this process (timer tick vs. a manual flush from a test or the demo).
    // Across several instances you'd claim rows instead: UPDATE … SET LockedUntil, or FOR UPDATE SKIP LOCKED.
    private readonly SemaphoreSlim _gate = new(1, 1);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(options.Value.PollInterval);
        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            try
            {
                await DispatchPendingAsync(stoppingToken);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                // The database may be briefly unavailable: log and try again on the next tick.
                logger.LogError(ex, "Outbox polling failed");
            }
        }
    }

    /// <summary>Delivers every due message once. Public so tests (and the demo) can flush deterministically.</summary>
    public async Task<int> DispatchPendingAsync(CancellationToken ct = default)
    {
        await _gate.WaitAsync(ct);
        try
        {
            using var scope = scopes.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<TDbContext>();
            var max = options.Value.MaxAttempts;

            var batch = await db.Set<OutboxMessage>()
                .Where(m => m.ProcessedAt == null && m.Attempts < max)
                .OrderBy(m => m.OccurredAt)
                .Take(options.Value.BatchSize)
                .ToListAsync(ct);

            foreach (var message in batch)
                await DeliverAsync(message, ct);

            await db.SaveChangesAsync(ct);
            return batch.Count;
        }
        finally
        {
            _gate.Release();
        }
    }

    /// <summary>Publishes an already-processed message again: what a broker does after a lost ack.</summary>
    public async Task<bool> RedeliverAsync(Guid messageId, CancellationToken ct = default)
    {
        using var scope = scopes.CreateScope();
        var message = await scope.ServiceProvider.GetRequiredService<TDbContext>().Set<OutboxMessage>()
            .AsNoTracking().FirstOrDefaultAsync(m => m.Id == messageId, ct);
        if (message is null) return false;

        await PublishInOwnScopeAsync(message, ct);
        return true;
    }

    private async Task DeliverAsync(OutboxMessage message, CancellationToken ct)
    {
        message.Attempts++;
        try
        {
            await PublishInOwnScopeAsync(message, ct);
            message.ProcessedAt = DateTime.UtcNow;
            message.Error = null;
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            // Retried on the next tick. In production: exponential backoff (NextAttemptAt column).
            message.Error = ex.Message.Length > 500 ? ex.Message[..500] : ex.Message;
            logger.LogWarning(ex, "Outbox message {Id} ({Type}) failed, attempt {Attempt}/{Max}: {Error}",
                message.Id, message.Type, message.Attempts, options.Value.MaxAttempts, message.Error);
        }
    }

    private async Task PublishInOwnScopeAsync(OutboxMessage message, CancellationToken ct)
    {
        if (!DomainEventTypes.ByName.TryGetValue(message.Type, out var type))
            throw new InvalidOperationException($"Unknown event type '{message.Type}'");

        var @event = (IDomainEvent)JsonSerializer.Deserialize(message.Payload, type, JsonSerializerOptions.Web)!;

        // One scope per message: handlers get fresh DbContexts, a failure cannot leak into the next message.
        using var scope = scopes.CreateScope();
        var context = scope.ServiceProvider.GetRequiredService<MessageContext>();
        context.MessageId = message.Id;
        context.Attempt = message.Attempts;
        await scope.ServiceProvider.GetRequiredService<IEventBus>().PublishAsync(@event, ct);
    }

    public override void Dispose()
    {
        _gate.Dispose();
        base.Dispose();
    }
}

public static class MessagingServiceCollectionExtensions
{
    /// <summary>Outbox relay for one module's DbContext + the in-process bus it publishes to.</summary>
    public static IServiceCollection AddOutbox<TDbContext>(this IServiceCollection services, IConfiguration configuration)
        where TDbContext : DbContext
    {
        services.Configure<OutboxOptions>(configuration.GetSection("Outbox"));
        services.AddScoped<IEventBus, InProcessEventBus>();
        services.AddScoped<MessageContext>();
        services.AddSingleton<HandlerFaults>();
        // Singleton + hosted service = the SAME instance: tests and endpoints can call DispatchPendingAsync.
        services.AddSingleton<OutboxDispatcher<TDbContext>>();
        services.AddHostedService(sp => sp.GetRequiredService<OutboxDispatcher<TDbContext>>());
        return services;
    }
}

using System.Text.Json;
using DevLab.Api.Infrastructure.Events;
using Microsoft.EntityFrameworkCore;

namespace DevLab.Api.Infrastructure.Messaging;

/// <summary>
/// An event waiting to be delivered, stored in the SAME database (and the same transaction)
/// as the business change that raised it. Either both are committed, or neither: no dual write.
/// </summary>
public sealed class OutboxMessage
{
    public Guid Id { get; init; } = Guid.CreateVersion7();     // time-ordered → good index locality
    public required string Type { get; init; }                 // logical name (OrderPlaced), never a CLR assembly name
    public required string Payload { get; init; }              // JSON
    public DateTime OccurredAt { get; init; } = DateTime.UtcNow;
    public DateTime? ProcessedAt { get; set; }
    public int Attempts { get; set; }
    public string? Error { get; set; }

    public static OutboxMessage From<TEvent>(TEvent @event) where TEvent : IDomainEvent => new()
    {
        Type = typeof(TEvent).Name,
        Payload = JsonSerializer.Serialize(@event, JsonSerializerOptions.Web),
    };
}

/// <summary>Remembers which message each handler already processed: the consumer side of at-least-once.</summary>
public sealed class InboxRecord
{
    public Guid MessageId { get; init; }
    public required string Handler { get; init; }
    public DateTime ProcessedAt { get; init; } = DateTime.UtcNow;
}

public static class MessagingModelBuilderExtensions
{
    public static ModelBuilder AddOutbox(this ModelBuilder modelBuilder) => modelBuilder.Entity<OutboxMessage>(e =>
    {
        e.ToTable("OutboxMessages");
        e.Property(m => m.Type).HasMaxLength(120);
        e.Property(m => m.Error).HasMaxLength(500);
        // The dispatcher's query: "WHERE ProcessedAt IS NULL ORDER BY OccurredAt".
        e.HasIndex(m => new { m.ProcessedAt, m.OccurredAt });
    });

    public static ModelBuilder AddInbox(this ModelBuilder modelBuilder) => modelBuilder.Entity<InboxRecord>(e =>
    {
        e.ToTable("InboxRecords");
        // The primary key IS the deduplication: a second insert for the same pair fails.
        e.HasKey(r => new { r.MessageId, r.Handler });
        e.Property(r => r.Handler).HasMaxLength(120);
    });
}

backend/DevLab.Api/Infrastructure/Module.content:
namespace DevLab.Api.Infrastructure.Modules;

/// <summary>
/// A module = a bounded business area (Orders, Products…) that owns its data, its endpoints
/// and its services. Program.cs does not know the modules by name: it discovers them.
/// In a multi-project solution each module is its own assembly, referenced only through
/// its *.PublicApi project. Here they are folders in one assembly, and an architecture test
/// (ModuleBoundariesTests) enforces the same rule.
/// </summary>
public interface IModule
{
    void Register(IServiceCollection services, IConfiguration configuration);
}

/// <summary>One class per endpoint (a "slice"): found by assembly scanning, mapped automatically.</summary>
public interface IApiEndpoint
{
    void Map(IEndpointRouteBuilder app);
}

using System.Reflection;

namespace DevLab.Api.Infrastructure.Modules;

public static class ModuleExtensions
{
    /// <summary>Instantiates every IModule in the assembly and lets it register its services.</summary>
    public static IServiceCollection AddModules(this IServiceCollection services, IConfiguration configuration, Assembly assembly)
    {
        foreach (var module in Discover<IModule>(assembly))
            module.Register(services, configuration);
        return services;
    }

    /// <summary>Instantiates every IApiEndpoint and maps it. Adding a slice = adding a file, nothing else.</summary>
    public static IEndpointRouteBuilder MapApiEndpoints(this IEndpointRouteBuilder app, Assembly assembly)
    {
        foreach (var endpoint in Discover<IApiEndpoint>(assembly))
            endpoint.Map(app);
        return app;
    }

    private static IEnumerable<T> Discover<T>(Assembly assembly) =>
        assembly.GetTypes()
            .Where(t => typeof(T).IsAssignableFrom(t) && t is { IsAbstract: false, IsInterface: false })
            .Select(t => (T)Activator.CreateInstance(t)!);
}

