import { HttpClient } from '@angular/common/http';
import { Component, inject, signal } from '@angular/core';
import { forkJoin, map, of, catchError } from 'rxjs';
import { AuthStore } from '../../core/auth/auth.store';
import { LessonShell } from '../../shared/lesson-shell';
import { Json2Pipe } from '../../shared/json-view';
import { lessonById } from '../catalog';

interface Check { policy: string; url: string; rule: string; status?: number; }

@Component({
  selector: 'lesson-authorization',
  imports: [LessonShell, Json2Pipe],
  template: `
    <lesson-shell [lesson]="lesson">
      <div explain>
        <h3>Authentification ≠ Autorisation</h3>
        <p>L'authentification produit un <code>ClaimsPrincipal</code>. L'autorisation répond « peut-il faire ça ? » à partir des <strong>claims</strong>.
        Une <strong>policy</strong> est une liste de <em>requirements</em> ; chaque requirement est évalué par un ou plusieurs <em>handlers</em>. Si un handler
        appelle <code>Succeed</code>, c'est bon ; sinon → 403 (ou 401 si pas authentifié du tout).</p>
        <table>
          <tr><th>Policy</th><th>Règle</th><th>Quand l'utiliser</th></tr>
          <tr><td>AdminOnly</td><td><code>RequireRole("Admin")</code></td><td>rôles simples</td></tr>
          <tr><td>CanWriteProducts</td><td><code>RequireClaim("permission", "products:write")</code></td><td>permissions fines, découplées des rôles</td></tr>
          <tr><td>Adult</td><td><code>MinimumAgeRequirement(18)</code> + handler</td><td>logique custom réutilisable</td></tr>
          <tr><td>ServiceOrAdmin</td><td><code>RequireAssertion(ctx => …)</code></td><td>lambda rapide</td></tr>
          <tr><td>DocumentOwner</td><td><code>IAuthorizationService.AuthorizeAsync(user, doc, policy)</code></td><td>la décision dépend de la <strong>ressource</strong></td></tr>
        </table>
        <div class="callout" style="margin-top:.75rem"><strong>Multi-schemes :</strong> le scheme par défaut <code>Smart</code> regarde la requête (<code>X-Api-Key</code> ? <code>Bearer</code> ? sinon cookie) et délègue. Les policies ne savent même pas d'où viennent les claims. Teste la matrice avec un JWT (alice/bob/carol) <em>ou</em> une API key.</div>
      </div>

      <div demo class="col">
        <div class="row">
          <span class="badge">identité JWT : {{ auth.userName() ?? 'anonyme' }} {{ auth.roles().length ? '(' + auth.roles().join(', ') + ')' : '' }}</span>
          <button class="sm" (click)="auth.login('alice', 'alice123').subscribe(() => run())">alice</button>
          <button class="sm" (click)="auth.login('bob', 'bob123').subscribe(() => run())">bob</button>
          <button class="sm" (click)="auth.login('carol', 'carol123').subscribe(() => run())">carol</button>
          <button class="sm" (click)="auth.logout(); run()">anonyme</button>
          <input [value]="apiKey()" (input)="apiKey.set($any($event.target).value)" placeholder="ou X-Api-Key" style="width:160px">
          <button class="primary sm" (click)="run()">Tester la matrice</button>
        </div>
        <table>
          <tr><th>policy</th><th>règle</th><th>résultat</th></tr>
          @for (c of checks(); track c.policy) {
            <tr><td><code>{{ c.policy }}</code></td><td class="muted small">{{ c.rule }}</td>
              <td><span class="badge" [class.ok]="c.status === 200" [class.err]="c.status === 403" [class.warn]="c.status === 401">{{ c.status ?? '…' }} {{ c.status === 200 ? 'autorisé' : c.status === 403 ? 'interdit' : c.status === 401 ? 'non authentifié' : '' }}</span></td></tr>
          }
        </table>
        <div class="card">
          <h3>Resource-based : GET /api/authz/documents/:id</h3>
          <div class="row">
            @for (d of [1, 2, 3]; track d) { <button class="sm" (click)="doc(d)">document {{ d }}</button> }
            <span class="muted small">1 = alice, 2 = bob, 3 = carol. Admin voit tout.</span>
          </div>
          <pre class="json">{{ docResult() | json2 }}</pre>
        </div>
      </div>
    </lesson-shell>
  `,
})
export class AuthorizationLesson {
  readonly lesson = lessonById('authorization')!;
  readonly auth = inject(AuthStore);
  private readonly http = inject(HttpClient);
  readonly apiKey = signal('');
  readonly docResult = signal<unknown>(null);
  readonly checks = signal<Check[]>([
    { policy: 'AdminOnly', url: '/api/authz/admin', rule: 'rôle Admin' },
    { policy: 'CanWriteProducts', url: '/api/authz/write', rule: 'claim permission=products:write' },
    { policy: 'Adult', url: '/api/authz/adult', rule: 'claim age ≥ 18 (requirement custom)' },
    { policy: 'ServiceOrAdmin', url: '/api/authz/service', rule: 'assertion : rôle Service ou Admin' },
  ]);

  constructor() { this.run(); }

  private headers(): Record<string, string> { return this.apiKey() ? { 'X-Api-Key': this.apiKey() } : {}; }

  run() {
    const calls = this.checks().map(c => this.http.get(c.url, { headers: this.headers() }).pipe(
      map(() => 200), catchError(e => of(e.status as number))));
    forkJoin(calls).subscribe(statuses => this.checks.update(list => list.map((c, i) => ({ ...c, status: statuses[i] }))));
  }

  doc(id: number) {
    this.http.get(`/api/authz/documents/${id}`, { headers: this.headers() })
      .subscribe({ next: r => this.docResult.set(r), error: e => this.docResult.set({ status: e.status, hint: e.status === 403 ? 'pas propriétaire ni Admin' : e.status === 401 ? 'connecte-toi' : e.error }) });
  }
}

frontend/src/app/lessons/auth/cookie.ts.content:
import { HttpClient } from '@angular/common/http';
import { Component, inject, signal } from '@angular/core';
import { LessonShell } from '../../shared/lesson-shell';
import { Json2Pipe } from '../../shared/json-view';
import { lessonById } from '../catalog';

@Component({
  selector: 'lesson-cookie',
  imports: [LessonShell, Json2Pipe],
  template: `
    <lesson-shell [lesson]="lesson">
      <div explain>
        <h3>Le navigateur porte la session</h3>
        <p><code>SignInAsync</code> sérialise le <code>ClaimsPrincipal</code> dans un <strong>ticket chiffré</strong> (Data Protection) et le pose en cookie
        <code>HttpOnly</code> : JavaScript ne peut pas le lire, donc une faille XSS ne peut pas le voler. Le navigateur le renvoie tout seul à chaque requête —
        c'est à la fois la force (rien à gérer côté Angular) et le danger : <strong>CSRF</strong>.</p>
        <h3>CSRF en 2 lignes</h3>
        <p>Un site malveillant fait <code>POST /api/transfer</code> depuis ta session : le cookie part avec. Défenses : <code>SameSite=Lax/Strict</code>, et un
        <strong>token antiforgery</strong> que seul ton front connaît : le serveur pose un cookie lisible <code>XSRF-TOKEN</code>, Angular le recopie dans le header
        <code>X-XSRF-TOKEN</code> (via <code>withXsrfConfiguration</code>), le serveur compare les deux moitiés.</p>
        <div class="callout">Ici Angular et l'API sont servis sur la même origine (proxy dev <code>/api → :5080</code>). En cross-origin, il faudrait <code>withCredentials: true</code> côté Angular et <code>AllowCredentials()</code> + origine explicite côté CORS, et <code>SameSite=None; Secure</code>.</div>
        <p class="small muted">Cookie vs JWT ? Cookie pour une app web « classique » servie par le même domaine (simple, sûr). JWT pour des APIs consommées par plusieurs clients (mobile, autres services), ou une architecture stateless.</p>
      </div>

      <div demo class="col">
        <div class="row">
          <button class="primary" (click)="login('bob', 'bob123')">POST /cookie/login (bob)</button>
          <button (click)="me()">GET /cookie/me</button>
          <button (click)="logout()">POST /cookie/logout</button>
        </div>
        <p class="small muted"><code>document.cookie</code> vu par JS : <code>{{ visibleCookies() || '(rien — devlab.auth est HttpOnly)' }}</code></p>
        <div class="card">
          <h3>Attaque CSRF simulée : POST /cookie/transfer</h3>
          <div class="row">
            <button class="danger" (click)="clearXsrf(); transfer()">1 · sans token XSRF → 400</button>
            <button (click)="getXsrf()">2 · GET /cookie/csrf (pose XSRF-TOKEN)</button>
            <button class="primary" (click)="transfer()">3 · avec token → 200</button>
          </div>
          <p class="small muted">Regarde le panneau Réseau : après l'étape 2, Angular ajoute <code>X-XSRF-TOKEN</code> tout seul sur les POST.</p>
        </div>
        <pre class="json">{{ result() | json2 }}</pre>
      </div>
    </lesson-shell>
  `,
})
export class CookieLesson {
  readonly lesson = lessonById('auth-cookie')!;
  private readonly http = inject(HttpClient);
  readonly result = signal<unknown>(null);
  readonly visibleCookies = signal(document.cookie);

  private show = { next: (r: unknown) => { this.result.set(r); this.visibleCookies.set(document.cookie); },
                   error: (e: { status: number; error: unknown }) => { this.result.set({ status: e.status, body: e.error }); this.visibleCookies.set(document.cookie); } };

  login(userName: string, password: string) { this.http.post('/api/auth/cookie/login', { userName, password }).subscribe(this.show); }
  me() { this.http.get('/api/auth/cookie/me').subscribe(this.show); }
  logout() { this.http.post('/api/auth/cookie/logout', {}).subscribe(this.show); }
  getXsrf() { this.http.get('/api/auth/cookie/csrf').subscribe(this.show); }
  transfer() { this.http.post('/api/auth/cookie/transfer', {}).subscribe(this.show); }
  clearXsrf() { document.cookie = 'XSRF-TOKEN=; Max-Age=0; path=/'; this.visibleCookies.set(document.cookie); }
}

frontend/src/app/lessons/auth/jwt.ts.content:
import { HttpClient } from '@angular/common/http';
import { Component, computed, inject, input, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthStore } from '../../core/auth/auth.store';
import { LessonShell } from '../../shared/lesson-shell';
import { Json2Pipe } from '../../shared/json-view';
import { lessonById } from '../catalog';

@Component({
  selector: 'lesson-jwt',
  imports: [LessonShell, FormsModule, Json2Pipe],
  template: `
    <lesson-shell [lesson]="lesson">
      <div explain>
        <h3>Le contrat</h3>
        <ol class="steps">
          <li><strong>Login</strong> : identifiants → <code>access token</code> (JWT signé, 60 s ici, 5–15 min en prod) + <code>refresh token</code> (opaque, stocké côté serveur).</li>
          <li><strong>Appels API</strong> : <code>Authorization: Bearer &lt;access&gt;</code>. Le serveur vérifie la <em>signature</em>, l'<em>issuer</em>, l'<em>audience</em> et l'<em>expiration</em> — sans toucher à la base : c'est <strong>stateless</strong>.</li>
          <li><strong>Expiration</strong> → 401 → l'interceptor appelle <code>/refresh</code> → nouveau couple, l'ancien refresh est <strong>révoqué</strong> (rotation) → la requête est rejouée.</li>
          <li><strong>Logout</strong> : on révoque les refresh tokens. L'access token reste valide jusqu'à expiration : c'est POURQUOI il doit être court.</li>
        </ol>
        <div class="callout warn"><strong>Où stocker le token ?</strong> En mémoire (signal) + <code>sessionStorage</code> ici. Le <code>localStorage</code> est lisible par n'importe quel script XSS. L'alternative robuste : refresh token en cookie HttpOnly + access token en mémoire (le « BFF light »).</div>
        <p class="small muted">HS256 (clé symétrique) suffit quand émetteur = consommateur. Avec plusieurs APIs, passe à RS256/ES256 : l'API vérifie avec la clé publique (JWKS), sans connaître le secret.</p>
      </div>

      <div demo class="grid-2">
        <div class="card col">
          <h3>Login</h3>
          @if (returnUrl()) { <div class="callout">Le guard t'a redirigé ici depuis <code>{{ returnUrl() }}</code>.</div> }
          <div class="row">
            @for (u of users; track u.name) { <button class="sm" (click)="userName = u.name; password = u.pwd">{{ u.name }}</button> }
          </div>
          <input [(ngModel)]="userName" placeholder="utilisateur" autocomplete="username">
          <input [(ngModel)]="password" type="password" placeholder="mot de passe" autocomplete="current-password">
          <div class="row">
            <button class="primary" (click)="login()">POST /api/auth/jwt/login</button>
            <button (click)="auth.logout()" [disabled]="!auth.isLoggedIn()">Logout</button>
          </div>
          @if (error()) { <div class="callout err">{{ error() }}</div> }

          <h3 style="margin-top:1rem">Jouer avec le token</h3>
          <div class="row">
            <button (click)="callMe()" [disabled]="!auth.isLoggedIn()">GET /me</button>
            <button (click)="refresh()" [disabled]="!auth.refreshToken()">POST /refresh (manuel)</button>
            <button class="danger" (click)="auth.corruptAccessToken()" [disabled]="!auth.isLoggedIn()">Corrompre la signature</button>
          </div>
          <p class="small muted">Attends 60 s puis clique GET /me : le panneau Réseau montre 401 → refresh → 200. Ou corromps le token pour ne pas attendre.</p>
          <pre class="json">{{ meResult() | json2 }}</pre>
        </div>

        <div class="card col">
          <h3>État (AuthStore, signals)</h3>
          <div class="row">
            <span class="badge" [class.ok]="auth.isLoggedIn() && !auth.isExpired()" [class.err]="auth.isExpired()">{{ auth.isLoggedIn() ? (auth.isExpired() ? 'expiré' : 'connecté') : 'anonyme' }}</span>
            @if (auth.isLoggedIn()) {
              <span class="badge brand">{{ auth.userName() }}</span>
              <span class="badge">{{ auth.roles().join(', ') }}</span>
              <span class="badge" [class.warn]="auth.expiresInSeconds() < 15">expire dans {{ auth.expiresInSeconds() }} s</span>
            }
          </div>
          <div class="ttl"><div class="fill" [style.width.%]="ttlPercent()"></div></div>
          <h3>Access token décodé</h3>
          <p class="small muted">Un JWT n'est pas chiffré, juste <em>signé</em> : n'importe qui peut le lire. N'y mets rien de secret.</p>
          <div class="jwt mono">
            @if (auth.accessToken(); as t) {
              <span class="h">{{ t.split('.')[0] }}</span>.<span class="p">{{ t.split('.')[1] }}</span>.<span class="s">{{ t.split('.')[2] }}</span>
            } @else { <span class="muted">—</span> }
          </div>
          <pre class="json">{{ auth.payload() | json2 }}</pre>
          <p class="small muted">refresh token (opaque, jamais un JWT) : <code>{{ (auth.refreshToken() ?? '—').slice(0, 24) }}…</code></p>
        </div>
      </div>
    </lesson-shell>
  `,
  styles: [`
    .ttl { height: 6px; background: var(--bg-3); border-radius: 99px; overflow: hidden; margin: .5rem 0; }
    .fill { height: 100%; background: linear-gradient(90deg, var(--ok), var(--warn)); transition: width 1s linear; }
    .jwt { word-break: break-all; font-size: .72rem; background: #0a0e17; padding: .6rem; border-radius: 8px; border: 1px solid var(--border); }
    .h { color: #fb7185; } .p { color: #c4b5fd; } .s { color: #67e8f9; }
  `],
})
export class JwtLesson {
  readonly lesson = lessonById('auth-jwt')!;
  readonly auth = inject(AuthStore);
  private readonly http = inject(HttpClient);
  private readonly router = inject(Router);
  readonly returnUrl = input<string>();   // ?returnUrl= bound thanks to withComponentInputBinding

  readonly users = [{ name: 'alice', pwd: 'alice123' }, { name: 'bob', pwd: 'bob123' }, { name: 'carol', pwd: 'carol123' }];
  userName = 'alice'; password = 'alice123';
  readonly error = signal<string | null>(null);
  readonly meResult = signal<unknown>(null);
  readonly ttlPercent = computed(() => Math.min(100, (this.auth.expiresInSeconds() / 60) * 100));

  login() {
    this.error.set(null);
    this.auth.login(this.userName, this.password).subscribe({
      next: () => { const back = this.returnUrl(); if (back) this.router.navigateByUrl(back); },
      error: e => this.error.set(`${e.status} — ${e.error?.title ?? 'échec'}`),
    });
  }
  callMe() { this.http.get('/api/auth/jwt/me').subscribe({ next: r => this.meResult.set(r), error: e => this.meResult.set({ status: e.status, error: e.error }) }); }
  refresh() { this.auth.refresh().subscribe({ error: e => this.error.set(`refresh: ${e.status}`) }); }
}

